import fs from "node:fs";
import path from "node:path";

const root = process.cwd();
const designedDir = path.join(root, "public", "designed");

function read(locale, file) {
  return fs.readFileSync(path.join(designedDir, locale, file), "utf8");
}

function write(locale, file, content) {
  fs.writeFileSync(path.join(designedDir, locale, file), content, "utf8");
}

function replaceMany(content, replacements) {
  let next = content;
  for (const [from, to] of replacements) {
    next = next.replaceAll(from, to);
  }
  return next;
}

function patch(locale, file, replacements) {
  write(locale, file, replaceMany(read(locale, file), replacements));
}

